func mergeTwoLists(a *ListNode, b *ListNode) *ListNode {
	dummy := &ListNode{}
	tail := dummy
	for a != nil && b != nil {
		if a.Val <= b.Val {
			tail.Next = a
			a = a.Next
		} else {
			tail.Next = b
			b = b.Next
		}
		tail = tail.Next
	}
	if a != nil {
		tail.Next = a
	} else {
		tail.Next = b
	}
	return dummy.Next
}

func sortList(head *ListNode) *ListNode {
	if head == nil || head.Next == nil {
		return head
	}

	slow := head
	fast := head.Next
	for fast != nil && fast.Next != nil {
		slow = slow.Next
		fast = fast.Next.Next
	}

	mid := slow.Next
	slow.Next = nil

	return mergeTwoLists(sortList(head), sortList(mid))
}

class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  private ListNode mergeTwoLists(ListNode a, ListNode b) {
    ListNode dummy = new ListNode(0);
    ListNode tail = dummy;
    while (a != null && b != null) {
      if (a.val <= b.val) {
        tail.next = a;
        a = a.next;
      } else {
        tail.next = b;
        b = b.next;
      }
      tail = tail.next;
    }
    tail.next = a != null ? a : b;
    return dummy.next;
  }

  public ListNode sortList(ListNode head) {
    if (head == null || head.next == null) {
      return head;
    }

    ListNode slow = head;
    ListNode fast = head.next;
    while (fast != null && fast.next != null) {
      slow = slow.next;
      fast = fast.next.next;
    }

    ListNode mid = slow.next;
    slow.next = null;

    return mergeTwoLists(sortList(head), sortList(mid));
  }
}

class Solution:
    def sortList(self, head: Optional[ListNode]) -> Optional[ListNode]:
        if not head or not head.next:
            return head

        slow, fast = head, head.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next

        mid = slow.next
        slow.next = None

        left = self.sortList(head)
        right = self.sortList(mid)
        return self._merge(left, right)

    def _merge(self, a: Optional[ListNode], b: Optional[ListNode]) -> Optional[ListNode]:
        dummy = ListNode(0)
        tail = dummy
        while a and b:
            if a.val <= b.val:
                tail.next = a
                a = a.next
            else:
                tail.next = b
                b = b.next
            tail = tail.next
        tail.next = a if a else b
        return dummy.next

impl Solution {
  pub fn sort_list(head: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    let mut len = 0;
    let mut p = head.as_ref();
    while let Some(node) = p {
      len += 1;
      p = node.next.as_ref();
    }
    if len < 2 {
      return head;
    }

    let mut head = head;
    let mut split = &mut head;
    for _ in 0..(len / 2 - 1) {
      split = &mut split.as_mut().unwrap().next;
    }
    let right = split.as_mut().unwrap().next.take();
    let left = head;

    Solution::merge_two_lists(Solution::sort_list(left), Solution::sort_list(right))
  }

  fn merge_two_lists(a: Option<Box<ListNode>>, b: Option<Box<ListNode>>) -> Option<Box<ListNode>> {
    let mut dummy = ListNode::new(0);
    let mut tail = &mut dummy;
    let mut a = a;
    let mut b = b;
    while a.is_some() && b.is_some() {
      let take_a = a.as_ref().unwrap().val <= b.as_ref().unwrap().val;
      let mut node = if take_a { a.take().unwrap() } else { b.take().unwrap() };
      let next = node.next.take();
      tail.next = Some(node);
      tail = tail.next.as_mut().unwrap();
      if take_a {
        a = next;
      } else {
        b = next;
      }
    }
    tail.next = if a.is_some() { a } else { b };
    dummy.next
  }
}

const mergeTwoLists = (a: ListNode | null, b: ListNode | null): ListNode | null => {
  const dummy = new ListNode(0);
  let tail: ListNode = dummy;
  while (a && b) {
    if (a.val <= b.val) {
      tail.next = a;
      a = a.next;
    } else {
      tail.next = b;
      b = b.next;
    }
    tail = tail.next;
  }
  tail.next = a ? a : b;
  return dummy.next;
};

const sortList = (head: ListNode | null): ListNode | null => {
  if (!head || !head.next) return head;

  let slow = head;
  let fast: ListNode | null = head.next;
  while (fast && fast.next) {
    slow = slow.next!;
    fast = fast.next.next;
  }

  const mid = slow.next;
  slow.next = null;

  return mergeTwoLists(sortList(head), sortList(mid));
};
